     * @throws GroupIdNotFoundException if the group does not exist at the committed offset.
     * @throws UnknownMemberIdException if the member does not exist at the committed offset.
     */
    public StreamsGroupMember validateStreamsGroupMember(
        String groupId,
        String memberId,
        long committedOffset
    ) throws GroupIdNotFoundException, UnknownMemberIdException {
        StreamsGroup group = streamsGroup(groupId, committedOffset);
        StreamsGroupMember member = group.members().get(memberId, committedOffset);
